    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
import math
# Pick alpha so that the trig denominator is not (numerically) zero
# and the identity-driven ratio remains numerically stable.
while True:
    alpha = rng.randint(1, 60)
    c = math.cos(alpha)
    denom = 2.0*c + math.cos(3*alpha)
    # Avoid near-singular cases
    if abs(denom) < 1e-8:
        continue
    # Choose a nontrivial rational beta away from 1 to prevent trivial bounds
    p = rng.randint(2, 12)
    q = rng.randint(2, 12)
    beta = p / q
    if beta <= 0:
        continue
    if abs(beta - 1.0) < 0.1:
        continue
    # Compute the interior stationary solution parameter t; must be positive
    t = ( -math.sqrt(2.0) * (beta ** 1.5) + math.sqrt(2.0 * beta**3 + 8.0) ) / 2.0
    if t <= 0:
        continue
    # Compute the implied maximal value to ensure it's nontrivial
    max_frac = 2.0 / (3.0 * (t ** (2.0/3.0)))
    trig_const = 5.0  # exact by Chebyshev identity
    answer_val = trig_const * max_frac
    if abs(answer_val - round(answer_val)) < 1e-6:
        # Avoid accidentally integer answers
        continue
    return {'alpha': alpha, 'beta': beta, 'beta_str': f'{p}/{q}'}

