    return (False, None)
alpha = assign['alpha']
beta = assign['beta']
if not isinstance(alpha, int) or alpha <= 0:
    # alpha must be a positive integer
    return (False, None)
if not (isinstance(beta, (int, float)) and beta > 0):
    return (False, None)
# Check trig stability and identity-driven constant ratio
c = math.cos(alpha)
denom = 2.0*c + math.cos(3*alpha)
if abs(denom) < 1e-12:
    # Denominator too small; problem instance ill-posed
    return (False, None)
num = 16.0*(c**5) - math.cos(5*alpha)
trig_ratio = num / denom
# The ratio must evaluate (numerically) to 5 by Chebyshev identities
if not (abs(trig_ratio - 5.0) < 1e-8):
    # Numerical instability or incorrect instance
    return (False, None)
# Compute the stationary point of the inner optimization via Lagrange multipliers
# Reduce by homogeneity: fix y = 1 (w.l.o.g.). Let x = a, z = c_var.
# The optimality conditions yield c_var^2 = (beta/2) * a and the scalar equation in t = a^{3/2}:
# t^2 + sqrt(2)*beta^{3/2}*t - 2 = 0, with the positive root giving the interior maximum.
t = ( -math.sqrt(2.0) * (beta ** 1.5) + math.sqrt(2.0 * beta**3 + 8.0) ) / 2.0
if not (t > 0):
    # No interior critical point; instance invalid
    return (False, None)
# Max value of (x^2 y + beta y^2 z)/(x^3 + y^3 + z^3) is 2/(3 a) with a = t^{2/3}
a_star = t ** (2.0/3.0)
inner_max = 2.0 / (3.0 * a_star)
final_val = 5.0 * inner_max
# Build an exact-form LaTeX answer using the provided rational string if available
beta_str = assign.get('beta_str', None)
if beta_str is None:
    # Fallback to decimal representation
    # keep concise to avoid overly long strings
    beta_str = f'{beta}'
exact_str = f"\\frac{{10}}{{3\\left(\\left(\\frac{{\\sqrt{{2({beta_str})^3 + 8}} - \\sqrt{{2}}({beta_str})^{{3/2}}}}{{2}}\\right)^{{2/3}}\\right)}}"
approx_str = f"{final_val:.6f}"
answer = f"### The final answer is: \\boxed{{{exact_str}}} \\quad \\text{{(approximately }}{approx_str}\\text{{)}}"
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

